def market_scrape():
    while True:
        if TRADEPOST:
            key, s1, s2 = TRADEPOST.popleft()
            if COMPANIES[s1]['price'] > COMPANIES[s2]['price']:
                #this is a good trade, yoink
                DB.getInstance().getUser(key).portfolio[s2] += 1
            else:
                #not a good trade
                DB.getInstance().getUser(key).portfolio[s1] += 1

