#!/usr/bin/env python3
import requests
import random
import string
import time
import json
import threading

BASE_URL = "http://android-dropper.csaw.io:4657"

# Helper to generate random key/username
def rand_str(n=10):
    return ''.join(random.choices(string.ascii_lowercase + string.digits, k=n))

# Helper to match user.py conventions (expecting /register, /buy, /sell endpoints etc)
def register(uid):
    resp = requests.post(f"{BASE_URL}/register", json={"key": uid})
    return resp.ok

def buy(uid, symb, amt):
    resp = requests.post(f"{BASE_URL}/buy", json={"key": uid, "symbol": symb, "amount": amt})
    try:
        return resp.json()
    except:
        return resp.text

def sell(uid, symb, amt):
    resp = requests.post(f"{BASE_URL}/sell", json={"key": uid, "symbol": symb, "amount": amt})
    try:
        return resp.json()
    except:
        return resp.text

def balance(uid):
    resp = requests.post(f"{BASE_URL}/balance", json={"key": uid})
    try:
        return resp.json().get("balance", 0)
    except:
        return resp.text

def flag(uid):
    resp = requests.post(f"{BASE_URL}/flag", json={"key": uid})
    try:
        return resp.json()
    except:
        return resp.text

if __name__ == "__main__":
    uid = rand_str(12)
    print(f"[*] Registering user: {uid}")
    if not register(uid):
        print("[!] Registration failed")
        exit(1)
    #
    # Find out available stock symbols if needed; for this script we guess one symbol
    symbol = "GME"  # can change if known, else can enumerate

    # Get current balance
    bal = balance(uid)
    print(f"[*] Initial balance: {bal}")
    try:
        bal = float(bal)  # Usually 1000.0
    except:
        print(f"[!] Failed to get a valid balance: {bal}")
        exit(1)

    # Buy as much of symbol as possible
